/* Shared board rules. Browser copy is generated by build-app-bundle.js. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.DJ48ClassroomBoardDomain=api;})(typeof globalThis==='undefined'?this:globalThis,function(){
  'use strict';
  const money=n=>Math.round((Number(n)||0)*100)/100;
  function dateKey(now=Date.now()){return new Date(Number(now)+9*3600000).toISOString().slice(0,10);}
  function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s||'')&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;}
  function period(quest,day){if(!validDate(day))throw Error('날짜를 확인해 주세요.');if(quest.repeatRule==='daily')return day;if(quest.repeatRule==='weekly'){const d=new Date(day+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return 'week-'+d.toISOString().slice(0,10);}return 'once';}
  function recordId(member,quest,day){const p=period(quest,day);return `${member}__${quest.id||quest.questId}${p==='once'?'':'__'+p}`;}
  function recordDay(r){const v=r.dateKey||r.activityDate;if(validDate(v))return v;const t=r.createdAt;const ms=typeof t==='number'?t:t?.toMillis?.()||t?.toDate?.()?.getTime?.()||t?._seconds*1000||t?.seconds*1000;return ms?dateKey(ms):'';}

  function inPeriod(r,q,day){if(r.periodKey)return r.periodKey===period(q,day);if(q.repeatRule==='once'||!q.repeatRule)return true;const d=recordDay(r);return d?period(q,d)===period(q,day):false;}
  function assigned(q,member){return !q.targetStudentIds?.length||q.targetStudentIds.includes(member);}
  function available(q,day){return q.active!==false&&q.saveEnabled!==false&&(!q.startDate||day>=q.startDate)&&(!q.endDate||day<=q.endDate);}
  function activeStudent(id,s,settings){return s.role==='student'&&s.active===true&&s.status==='active'&&String(s.grade)===String(settings.grade)&&String(s.classNumber)===String(settings.classNumber)&&s.classroomHidden!==true&&s.hiddenFromClassroom!==true&&!(settings.teacherMemberUserIds||[]).includes(id);}
  function totalPoints(wallets){return money(wallets.reduce((sum,w)=>sum+Math.max(0,Number(w.point??w.berry??0)||0),0));}
  const submissionTypes=['complete','rating','checklist','text','image'];
  function validateSubmission(q,raw={}){
    const type=q.submissionType||'complete', out={type};
    if(!submissionTypes.includes(type))throw Error('지원하지 않는 제출 유형입니다.');
    if(type==='rating'){if(!['high','middle','low'].includes(raw.rating))throw Error('상·중·하 중 하나를 선택해 주세요.');out.rating=raw.rating;}
    if(type==='text'){if(typeof raw.text!=='string'||!raw.text.trim()||raw.text.length>3000)throw Error('내용은 1~3000자로 작성해 주세요.');out.text=raw.text.trim();}
    if(type==='checklist'){const items=q.checklistItems||[];if(!items.length)throw Error('선생님이 체크 항목을 설정해야 합니다.');if(!Array.isArray(raw.checked)||raw.checked.some(i=>!Number.isInteger(i)||i<0||i>=items.length))throw Error('체크 항목을 확인해 주세요.');out.checked=[...new Set(raw.checked)];out.labels=items;}
    if(type==='image'){const v=String(raw.imageData||'');if(!/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/]+=*$/.test(v)||v.length>180000)throw Error('이미지를 다시 선택해 주세요.');out.imageData=v;out.caption=String(raw.caption||'').slice(0,300);}
    return out;
  }
  function previewImport(input={},catalog={}){
    if(!input || typeof input!=='object' || Array.isArray(input)) input={};
    const issues=[],records=[],wallets=[],seen=new Set(),mappedStudents=new Set(),maps=input.maps||{};
    const issue=(kind,id,message)=>issues.push({kind,id:String(id||''),message});
    if(input.version!==1||input.source!=='grownd')issue('schema','','version=1, source=grownd 형식이 필요합니다.');
    if(!validDate(input.asOf))issue('date','','기준 날짜가 필요합니다.');
    const students=new Set((catalog.students||[]).map(s=>s.memberUserId)),quests=new Map((catalog.quests||[]).map(q=>[q.id,q])),gems=new Set((catalog.gems||[]).map(g=>g.gemId||g.id));
    const exclusions=new Map();
    for(const row of Array.isArray(input.excludedTargetStudents)?input.excludedTargetStudents:[]) { if(!row||!students.has(row.memberUserId)||typeof row.reason!=='string'||!row.reason.trim())issue('exclusion',row?.memberUserId,'제외 대상과 사유를 확인해 주세요.');else exclusions.set(row.memberUserId,row.reason.trim()); }
    const srcStudents=Array.isArray(input.students)?input.students:[];
    if(!srcStudents.length)issue('student','','원본 학생 목록이 없습니다.');
    for(const s of srcStudents){const id=String(s?.sourceId||''),target=maps.students?.[id];if(!id||seen.has('s:'+id)){issue('duplicate',id,'원본 학생 ID가 비었거나 중복입니다.');continue;}seen.add('s:'+id);if(s.role==='teacher')continue;if(!target||!students.has(target)){issue('student',id,'학급 학생에 명시적으로 매핑해야 합니다.');continue;}if(exclusions.has(target)){issue('exclusion',id,'이전 대상으로 매핑한 학생을 동시에 제외할 수 없습니다.');continue;}if(mappedStudents.has(target)){issue('student',id,'여러 원본 학생이 같은 대상으로 연결됐습니다.');continue;}mappedStudents.add(target);
      const amounts=[s.point,s.heartberry];if(amounts.some(v=>typeof v!=='number'||!Number.isFinite(v)||v<0||Math.abs(v*100-Math.round(v*100))>1e-7)){issue('currency',id,'잔액은 0 이상, 소수 둘째 자리까지 원본 값이 필요합니다.');continue;}
      wallets.push({sourceId:id,memberUserId:target,point:s.point,djCoin:s.heartberry});
    }
    if(input.records!==undefined&&!Array.isArray(input.records))issue('schema','','records는 배열이어야 합니다.');
    for(const r of Array.isArray(input.records)?input.records:[]){const id=String(r?.sourceId||''),member=maps.students?.[r?.studentId],qid=maps.quests?.[r?.questId],q=quests.get(qid);if(!id||seen.has('r:'+id)){issue('duplicate',id,'원본 기록 ID가 비었거나 중복입니다.');continue;}seen.add('r:'+id);
      if(!mappedStudents.has(member)||!q||!validDate(r.dateKey)){issue('mapping',id,'학생·활동 매핑 또는 날짜가 없습니다.');continue;}
      if(r.dateKey>input.asOf||!['completed','pending','incomplete'].includes(r.status)||typeof r.rewardPaid!=='boolean'){issue('record',id,'상태·지급 여부·기준일을 확인해 주세요.');continue;}
      if(!Array.isArray(r.gemIds)||r.gemIds.some(g=>!gems.has(maps.gems?.[g]))){issue('gem',id,'젬은 이름이 아닌 원본 ID와 대상 ID로 연결해야 합니다.');continue;}
      records.push({sourceId:id,source:'grownd',memberUserId:member,questId:qid,dateKey:r.dateKey,periodKey:period(q,r.dateKey),status:r.status,rewardPaid:r.rewardPaid,gemIds:r.gemIds.map(g=>maps.gems[g]),imported:true});
    }
    for(const s of catalog.students||[])if(!mappedStudents.has(s.memberUserId)&&!exclusions.has(s.memberUserId))issue('unmatched',s.memberUserId,'원본에 대응하는 학생이 없습니다. 별도 처리 결정을 기록해 주세요.');
    for(const item of catalog.shopItems||[])if(item.priceMissing===true||item.pricePoint===null||item.pricePoint===undefined&&item.priceCoin===undefined)issue('price',item.itemId,'상품 가격 확인 필요');
    const unsupported=Array.isArray(input.unsupported)?input.unsupported:[];for(const name of unsupported)issue('unsupported',name,'현재 이전 대상 밖의 데이터입니다.');
    return {ready:issues.length===0,issues,records,wallets,excludedTargetStudents:[...exclusions].map(([memberUserId,reason])=>({memberUserId,reason})),totals:{point:totalPoints(wallets),djCoin:money(wallets.reduce((a,w)=>a+w.djCoin,0))},currencyMap:{heartberry:'djCoin',point:'point'},mode:'preview-only'};
  }
  return {money,dateKey,validDate,period,recordId,recordDay,inPeriod,assigned,available,activeStudent,totalPoints,submissionTypes,validateSubmission,previewImport};
});
